// Synthetic messages and hand-authored provider responses. These measure the
// application safety/interpretation contract, not the live model's accuracy.
type Extracted = { type: "INCOME" | "EXPENSE"; categoryName: string | null };
const item = (categoryName: string | null = "Makanan & Minuman", type: "INCOME" | "EXPENSE" = "EXPENSE"): Extracted => ({ type, categoryName });
const add = (transactions: Extracted[]) => ({ intent: "add_transactions", transactions: transactions.map((item, index) => ({ ...item, sourceIndex: index + 1 })), requiresConfirmation: true });
const query = (value: object) => ({ query: value });
export type GoldenCase = { name: string; message: string; output: unknown; expected: "PROPOSAL" | "CLARIFICATION" | "QUERY" | "UNSUPPORTED"; amounts?: string[]; dates?: string[]; field?: string };
